#!/usr/bin/env bash
# ENCUT convergence scan for VASP: build directories, run or submit, collect.
#
# Usage (run inside this directory; POTCAR must be generated by you first):
#   bash run_encut_scan.sh prepare            # only create encut_<E>/ directories
#   bash run_encut_scan.sh run                # run them one after another (interactive / inside a job)
#   bash run_encut_scan.sh submit             # sbatch one job per directory (JOB_SCRIPT below)
#   bash run_encut_scan.sh collect            # write encut.dat and print a summary
#
# Optional environment variables:
#   ENCUTS="300 350 400 450 500 550 600"   explicit list in eV; default = factors x max(ENMAX)
#   FACTORS="1.0 1.1 1.2 1.3 1.4 1.5 1.6 1.8 2.0"
#   VASP="mpirun -np 8 vasp_std"           command used by "run"
#   JOB_SCRIPT=job_vasp.sh                 Slurm script used by "submit" (must run VASP in its cwd)
#
# encut.dat columns: ENCUT  E0(sigma->0, eV)  NIONS  pressure(kB)
# Plot with:  python ../plot_convergence.py encut.dat --xlabel "ENCUT (eV)"
set -euo pipefail

ACTION=${1:-}
FACTORS=${FACTORS:-"1.0 1.1 1.2 1.3 1.4 1.5 1.6 1.8 2.0"}
VASP=${VASP:-"mpirun -np 8 vasp_std"}
JOB_SCRIPT=${JOB_SCRIPT:-job_vasp.sh}
HERE=$(cd "$(dirname "$0")" && pwd)
cd "$HERE"

usage() { sed -n '2,17p' "$0"; exit 1; }
[ -n "$ACTION" ] || usage

if [ -z "${ENCUTS:-}" ]; then
  if [ -f POTCAR ]; then
    # largest ENMAX of all species, e.g. "ENMAX  =  245.345; ENMIN  =  184.009 eV"
    enmax=$(awk -F'[=;]' '/ENMAX/{v=$2+0; if (v>m) m=v} END{print m}' POTCAR)
    ENCUTS=$(for f in $FACTORS; do awk -v e="$enmax" -v f="$f" \
               'BEGIN{printf "%d ", int(e*f/10+0.5)*10}'; done)
    echo "max(ENMAX) = $enmax eV -> ENCUTS = $ENCUTS"
  else
    ENCUTS="250 300 350 400 450 500 550 600"
    echo "WARNING: no POTCAR here, using the fallback list: $ENCUTS" >&2
  fi
fi

prepare() {
  for f in INCAR.template POSCAR KPOINTS POTCAR; do
    [ -f "$f" ] || { echo "ERROR: $f missing (POTCAR: create it yourself, it is licensed)" >&2; exit 1; }
  done
  for e in $ENCUTS; do
    d=encut_$e
    mkdir -p "$d"
    sed "s/@ENCUT@/$e/" INCAR.template > "$d/INCAR"
    cp POSCAR KPOINTS POTCAR "$d/"
  done
  echo "prepared: $(for e in $ENCUTS; do printf 'encut_%s ' "$e"; done)"
}

case "$ACTION" in
  prepare)
    prepare ;;
  run)
    prepare
    for e in $ENCUTS; do
      echo ">>> ENCUT = $e eV"
      ( cd "encut_$e" && $VASP > vasp.out 2>&1 )
    done ;;
  submit)
    prepare
    [ -f "$JOB_SCRIPT" ] || { echo "ERROR: $JOB_SCRIPT not found (see Common chapter 2 or mkjob.py)" >&2; exit 1; }
    for e in $ENCUTS; do
      ( cd "encut_$e" && sbatch -J "encut$e" "$HERE/$JOB_SCRIPT" )
    done ;;
  collect)
    : > encut.dat
    for e in $ENCUTS; do
      o=encut_$e/OUTCAR
      [ -f "$o" ] || { echo "WARNING: $o not found, skipped" >&2; continue; }
      grep -q "General timing" "$o" || echo "WARNING: $o did not finish normally" >&2
      e0=$(grep "energy  without entropy" "$o" | tail -1 | awk '{print $NF}')
      n=$(grep -m1 "NIONS" "$o" | awk '{print $NF}')
      p=$(grep "external pressure" "$o" | tail -1 | awk '{print $4}')
      [ -n "$e0" ] && echo "$e $e0 $n ${p:-nan}" >> encut.dat
    done
    printf "%8s %16s %6s %10s\n" ENCUT "E0(eV)" NIONS "P(kB)"
    awk '{printf "%8s %16s %6s %10s\n", $1, $2, $3, $4}' encut.dat
    echo "written: encut.dat" ;;
  *)
    usage ;;
esac
